// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { PriceChart } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Finance/PriceChart)

figma.connect(PriceChart, FIGMA_NODE_URL, {
  props: {
    fill: figma.boolean('fill'),
    summary: figma.string('summary'),
  },
  example: ({ fill, summary }) => (
    <PriceChart fill={fill} summary={summary}></PriceChart>
  ),
});
